(* [comment removed for export] *)
Lemma sj_keep LB FF LK (M M' : word -> option byte) : sj_wf LB FF LK ->
  (forall b a, In b LB -> in_shadow_of (fst b) (snd b) a -> M' (Z_to_bv 64 a) = M (Z_to_bv 64 a)) ->
